#include <stdio.h>
#include <string.h>

#define MAX_SIZE 100

void getResult(int nums[], int nums_size);

int main() {
    int nums[MAX_SIZE];
    int nums_size = 0;

    while(scanf("%d", &nums[nums_size])) {
        nums_size++;
        if(getchar() != ' ') break;
    }

    if(nums_size == 0) {
        puts("[]");
    } else {
        getResult(nums, nums_size);
    }

    return 0;
}

void getResult(int nums[], int nums_size) {
    // i高->i+1矮 为true，i矮->i+1高 为false
    int flag = 1;

    for(int i=0; i<nums_size-1; i++) {
        if(nums[i] != nums[i+1] && (nums[i] > nums[i+1]) != flag) {
            int tmp = nums[i];
            nums[i] = nums[i+1];
            nums[i+1] = tmp;
        }

        flag = !flag;
    }

    char res[MAX_SIZE * 10] = {'\0'};
    for(int i=0; i<nums_size; i++) {
        char tmp[10];
        sprintf(tmp, "%d", nums[i]);
        strcat(res, tmp);

        if(i != nums_size - 1) {
            strcat(res, " ");
        }
    }

    puts(res);
}
